command -v python3>/dev/null 2>&1||{ echo python3_required;exit 127;};python3 -c 'import sys,json,math,hashlib;N=int(sys.argv[1])if len(sys.argv)>1 else 10;A=float(sys.argv[2])if len(sys.argv)>2 else 0;B=float(sys.argv[3])if len(sys.argv)>3 else 0;L=float(sys.argv[4])if len(sys.argv)>4 else .5;ip=lambda x:x>1 and all(x%d for d in range(2,int(math.isqrt(x))+1));P=[];x=2;exec("while len(P)<N:\n P+=([x]if ip(x)else[]);x+=1");p=P[-1];A=A or p;B=B or p;c=(1-L)*A+L*B;o=abs(c-p);E=lambda q:1-math.log(N+1)/math.log(q);d=abs(E(c)-E(p));z=o+d;q=json.dumps([N,L,p,c]);g=int.from_bytes(hashlib.sha512(q.encode()).digest(),"big");t=math.log(g)*14.134725;print(json.dumps({"P":"RM/Continuum/2KB/1","n":N,"lambda":L,"P_n":p,"C0":A,"C1":B,"C_lambda":c,"O":o,"dE":d,"Z":z,"ZE":o<=1e-12 and d<=1e-12,"G":str(g),"rho_star":"0.5+%.12fi"%t,"note":"formal model; rho_star is not a claimed zeta zero; not a proof of RH"},separators=(",",":")))' "$@"
